import Foundation
import Observation

/// The read-only hill database bundled with the app (generated by scripts/build_hills.py),
/// plus the hand-picked difficulty ratings and AllTrails routes (scripts/apply_curation.py).
@Observable
final class HillCatalog {
    let source: String
    let licence: String
    let lists: [HillList]
    let hills: [Hill]
    private let hillsByID: [Int: Hill]
    private let hillsByList: [String: [Hill]]
    private let guides: [Int: PeakGuide]

    struct File: Decodable {
        let source: String
        let licence: String
        let lists: [HillList]
        let hills: [Hill]
    }

    init(file: File, guides: [Int: PeakGuide] = [:]) {
        self.guides = guides
        source = file.source
        licence = file.licence
        lists = file.lists
        hills = file.hills
        hillsByID = Dictionary(uniqueKeysWithValues: file.hills.map { ($0.id, $0) })
        var byList: [String: [Hill]] = [:]
        for hill in file.hills {
            for list in hill.lists { byList[list, default: []].append(hill) }
        }
        hillsByList = byList.mapValues { $0.sorted { $0.metres > $1.metres } }
    }

    convenience init(data: Data, curation: Data? = nil) throws {
        let guides = try curation.map { try JSONDecoder().decode(PeakGuideFile.self, from: $0).byHillID } ?? [:]
        self.init(file: try JSONDecoder().decode(File.self, from: data), guides: guides)
    }

    static func bundled(_ bundle: Bundle = .main) -> HillCatalog {
        guard let url = bundle.url(forResource: "hills", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let catalog = try? HillCatalog(data: data, curation: curation(in: bundle))
        else { fatalError("hills.json or curation.json is missing or invalid; see the README") }
        return catalog
    }

    private static func curation(in bundle: Bundle) -> Data? {
        bundle.url(forResource: "curation", withExtension: "json").flatMap { try? Data(contentsOf: $0) }
    }

    func hill(id: Int) -> Hill? { hillsByID[id] }
    func list(id: String) -> HillList? { lists.first { $0.id == id } }
    func hills(in listID: String) -> [Hill] { hillsByList[listID] ?? [] }
    func guide(for hill: Hill) -> PeakGuide? { guides[hill.id] }
    func difficulty(of hill: Hill) -> Difficulty? { guides[hill.id]?.difficulty }

    /// Lists grouped by area, in the order the data file defines them.
    var listsByArea: [ListGroup] {
        var order: [String] = []
        var groups: [String: [HillList]] = [:]
        for list in lists {
            if groups[list.area] == nil { order.append(list.area) }
            groups[list.area, default: []].append(list)
        }
        return order.map { ListGroup(area: $0, lists: groups[$0]!) }
    }

    func progress(for listID: String, bagged: Set<Int>) -> ListProgress {
        let members = hills(in: listID)
        return ListProgress(bagged: members.filter { bagged.contains($0.id) }.count, total: members.count)
    }
}

struct ListGroup: Identifiable {
    let area: String
    let lists: [HillList]
    var id: String { area }
}

struct ListProgress: Equatable {
    let bagged: Int
    let total: Int
    var remaining: Int { total - bagged }
    var fraction: Double { total == 0 ? 0 : Double(bagged) / Double(total) }
    var isComplete: Bool { total > 0 && bagged == total }
}
